<?php $page_title='ขอคืนสินค้า';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$id=(int)($_GET['order_id']??0);$stmt=$db->prepare("SELECT * FROM orders WHERE id=? AND user_id=? AND order_status IN ('shipped','completed')");$stmt->execute([$id,(int)$_SESSION['user_id']]);$order=$stmt->fetch();if(!$order){header('Location: '.BASE_URL.'my-orders.php');exit;}$items=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$id]);$items=$items->fetchAll();require_once __DIR__.'/includes/header.php';?><div class="container" style="max-width:850px;margin:36px auto 70px"><a href="<?php echo BASE_URL;?>my-orders.php">← กลับคำสั่งซื้อ</a><section class="checkout-card" style="margin-top:18px"><p class="eyebrow">RETURN REQUEST</p><h1>ขอคืนสินค้า <?php echo e($order['order_no']);?></h1><p>เลือกสินค้าและจำนวนที่ต้องการคืน สามารถยื่นคำขอได้ภายใน 7 วันหลังรับสินค้า</p><form id="returnForm" enctype="multipart/form-data"><input type="hidden" name="action" value="create"><input type="hidden" name="order_id" value="<?php echo $id;?>"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><div style="display:grid;gap:10px;margin:20px 0"><?php foreach($items as $item):?><label style="display:grid;grid-template-columns:1fr 100px;gap:14px;align-items:center;border:1px solid var(--border-color);padding:14px"><span><strong><?php echo e($item['product_name'].($item['variant_name']?' · '.$item['variant_name']:''));?></strong><small style="display:block">ซื้อ <?php echo (int)$item['quantity'];?> ชิ้น · <?php echo formatCurrency($item['price']);?>/ชิ้น</small></span><select name="quantities[<?php echo (int)$item['id'];?>]"><option value="0">ไม่คืน</option><?php for($q=1;$q<=(int)$item['quantity'];$q++):?><option value="<?php echo $q;?>"><?php echo $q;?> ชิ้น</option><?php endfor;?></select></label><?php endforeach;?></div><label>เหตุผลการคืน<textarea name="reason" minlength="10" maxlength="500" rows="5" required></textarea></label><label>รูปหลักฐานสินค้า<input type="file" name="evidence_image" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG หรือ WebP ไม่เกิน 5 MB</small></label><button class="btn btn-primary">ส่งคำขอคืนสินค้า</button></form></section></div><script>document.getElementById('returnForm').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{const r=await fetch(`${BASE_URL}api/returns.php`,{method:'POST',body:new FormData(e.currentTarget)}),j=await r.json();if(j.status!=='success')throw new Error(j.message);showToast(j.message,'success');setTimeout(()=>location.href=j.data.redirect,600)}catch(x){showToast(x.message,'error');b.disabled=false}};</script><?php require_once __DIR__.'/includes/footer.php';?>
